// Deterministically hand a child an stdout pipe whose read end is already closed => EPIPE on write.
use std::os::unix::process::CommandExt;
use std::process::Command;
fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut fds = [0i32; 2];
    unsafe { assert_eq!(libc_pipe(&mut fds), 0); }
    let (rd, wr) = (fds[0], fds[1]);
    unsafe { close(rd); }               // read end closed BEFORE exec
    let mut cmd = Command::new(&args[0]);
    cmd.args(&args[1..]);
    unsafe { cmd.pre_exec(move || { if dup2(wr, 1) < 0 { return Err(std::io::Error::last_os_error()); } Ok(()) }); }
    let st = cmd.status().expect("spawn");
    match st.code() {
        Some(c) => println!("EXITCODE={}", c),
        None => println!("SIGNAL={:?}", signal_of(&st)),
    }
}
fn signal_of(st: &std::process::ExitStatus) -> i32 { use std::os::unix::process::ExitStatusExt; st.signal().unwrap_or(-1) }
extern "C" { fn pipe(fds: *mut i32) -> i32; fn close(fd: i32) -> i32; fn dup2(a: i32, b: i32) -> i32; }
unsafe fn libc_pipe(fds: &mut [i32;2]) -> i32 { pipe(fds.as_mut_ptr()) }

