use std::os::unix::process::CommandExt;
use std::process::Command;
extern "C" { fn pipe(fds: *mut i32) -> i32; fn close(fd: i32) -> i32; fn dup2(a: i32, b: i32) -> i32; fn signal(s: i32, h: usize) -> usize; }
fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut fds = [0i32; 2];
    unsafe { assert_eq!(pipe(fds.as_mut_ptr()), 0); }
    let (rd, wr) = (fds[0], fds[1]);
    unsafe { close(rd); }
    let mut cmd = Command::new(&args[0]);
    cmd.args(&args[1..]);
    unsafe { cmd.pre_exec(move || {
        signal(13, 1); // SIGPIPE -> SIG_IGN, inherited across exec
        if dup2(wr, 1) < 0 { return Err(std::io::Error::last_os_error()); } Ok(())
    }); }
    let st = cmd.status().expect("spawn");
    use std::os::unix::process::ExitStatusExt;
    match st.code() { Some(c) => println!("EXITCODE={}", c), None => println!("SIGNAL={}", st.signal().unwrap_or(-1)) }
}

